/*
 * QDOS/386 R13 - bitmap font renderer (independent of the display hardware).  See docs/R13-FONT-PROVENANCE.md.
 * Two fonts, chosen at build time; both are glyphs 5 pixels wide and 9 rows tall, drawn in a 6x10 cell:
 *   default            Minerva 1.98's QL fonts (GPL-2.0; kernel/font_minerva.c, generated by tools/r13-font/minerva-font.py
 *                      from the ROM and the GAS source): all 256 codes, QL character set ($60 pound, $7F copyright,
 *                      $80.. accented letters and symbols); codes $00..$1E show Minerva's invalid-character glyph.
 *   -DQDOS_FONT_QDOS5X9 the original QDOS5x9 fallback (tools/r13-font/qdos5x9.txt): codes 0x20..0x7E, every other code
 *                      shows the box glyph 0x7F.  For builds that must not carry GPL material.
 * Freestanding C89.
 */
#ifndef QDOS386_FONT_H
#define QDOS386_FONT_H

#define FONT_GLYPH_W   5
#define FONT_GLYPH_H   9
#define FONT_CELL_W    6
#define FONT_CELL_H    10
#define FONT_FIRST     0x20
#define FONT_MISSING   0x7F

#define FONT_A_UNDER   0x01u       /* underline: row 9 of the cell (below the descenders) */
#define FONT_A_INVERSE 0x02u       /* swap ink and paper */
#define FONT_A_BOLD    0x04u       /* ink also one pixel to the right (column 5 of the cell) */
#define FONT_A_NOPAPER 0x08u       /* draw ink only: paper pixels keep their value */

extern const unsigned char font5x9[96][9];
extern const unsigned char font_minerva[256][9];
extern const char font_name[];          /* "Minerva 1.98" or "QDOS5x9" */

/* The 9 row bytes of code c (bit 7 = leftmost pixel); the font's invalid-code glyph for codes it does not have. */
const unsigned char *font_glyph(unsigned int c);

/* Draw code c with its full 6x10 cell at (x, y) of an 8-bit buffer of w x h pixels and the given stride; clipped to
 * the buffer.  Returns 1 if any pixel was inside. */
int font_draw_cell(unsigned char *buf, unsigned int w, unsigned int h, unsigned int stride, int x, int y,
                   unsigned int c, unsigned int ink, unsigned int paper, unsigned int attr);

#endif
